/** UI projections of the FastAPI schemas. Browser fixtures are generated by that API. */
export type RunStatus = "processing" | "completed" | "partial" | "failed";
export interface BaseRun {
  id: string;
  video_id: string;
  status: RunStatus;
  created_at: string;
  warnings?: string[];
  error_code?: string | null;
  error_message?: string | null;
}
export interface Video extends BaseRun {
  original_filename: string;
  duration_seconds: number;
  size_bytes: number;
}
export interface Configuration {
  max_video_bytes: number;
  max_duration_seconds: number;
}
export interface Segment {
  id: number;
  start: number;
  end: number;
  text: string;
}
export interface TranscriptRun extends BaseRun {
  result: { segments: Segment[]; language: string | null } | null;
  text: string;
}
export interface Candidate {
  id: string;
  quote: string;
  start_seconds: number;
  end_seconds: number;
  reason: string;
  needs_context: boolean;
}
export interface ClaimRun extends BaseRun {
  transcript_run_id: string;
  candidates: Candidate[];
}
export interface Proposition {
  id: string;
  parent_candidate_id: string;
  text: string;
  kind: string;
  source_quote: string;
  start_seconds: number;
  end_seconds: number;
  needs_context: boolean;
}
export interface AtomicRun extends BaseRun {
  claim_run_id: string;
  results: {
    parent_candidate_id: string;
    source_quote: string;
    status: string;
    review_reason: string | null;
    propositions: Proposition[];
  }[];
}
export interface Passage {
  id: string;
  source_id: string;
  text: string;
  lexical_relevance: number;
}
export interface Source {
  id: string;
  final_url: string;
  title: string | null;
  publisher: string | null;
  publication_date: string | null;
  source_type: string;
  primary_secondary: string;
  metadata_origin: string;
}
export interface RetrievalRun extends BaseRun {
  decomposition_run_id: string;
  sources: Source[];
  results: {
    proposition_id: string;
    status: string;
    error_code: string | null;
    user_context: string | null;
    query: string;
    passages: Passage[];
    attempts: { url: string; status: string; error_code: string | null }[];
  }[];
}
export interface MappingRun extends BaseRun {
  request: { retrieval_run_id: string };
  results: {
    passage_id: string;
    proposition_id: string;
    status: string;
    citation_url: string;
    error_code: string | null;
    decision: {
      relationship: string | null;
      evidence_quote: string | null;
      explanation: string;
      caveats: string[];
    } | null;
  }[];
}
export interface RankingRun extends BaseRun {
  request: { mapping_run_id: string };
  groups: {
    id: string;
    source_ids: string[];
    independence: string;
    links: { reason: string; provenance: string }[];
  }[];
  results: {
    proposition_id: string;
    ranked: {
      passage_id: string;
      group_id: string;
      rank: number;
      relationship: string;
      directness: string;
      source_role: string;
      reasons: string[];
    }[];
  }[];
}
export interface Citation extends Omit<Source, "id" | "final_url"> {
  passage_id: string;
  source_id: string;
  group_id: string;
  url: string;
  quote: string;
  relationship: string;
  mapping_explanation: string;
  mapping_caveats: string[];
}
export interface Assessment {
  proposition_id: string;
  proposition_text: string;
  start_seconds: number;
  end_seconds: number;
  evidence_status: string;
  explanation: string;
  limitations: string[];
  scope: string;
  citations: Citation[];
  coverage: {
    retrieved_passages: number;
    selected_passages: number;
    mapped_passages: number;
    unresolved_passage_ids: string[];
    unmapped_passage_ids: string[];
    failed_fetch_count: number;
    retrieval_status: string;
  };
}
export interface VerificationRun extends BaseRun {
  request: { ranking_run_id: string };
  results: Assessment[];
  policy_version: string;
}
export interface ConfidenceResult {
  proposition_id: string;
  evidence_confidence: number;
  calibrated: false;
  raw_score: number;
  components: Record<
    string,
    { value: number; weight: number; points: number; explanation: string }
  >;
  caps: { maximum: number; reason: string }[];
  unknown_signals: Record<string, null>;
  limitations: string[];
}
export interface ConfidenceRun extends BaseRun {
  request: { verification_run_id: string };
  results: ConfidenceResult[];
  algorithm_version: string;
}
export interface Runs {
  transcript: TranscriptRun;
  claims: ClaimRun;
  atoms: AtomicRun;
  retrieval: RetrievalRun;
  mapping: MappingRun;
  ranking: RankingRun;
  verification: VerificationRun;
  confidence: ConfidenceRun;
}
export type Stage = keyof Runs;
export type AnyRun = Runs[Stage];
export type History = { [K in Stage]: Runs[K][] };
export type Selection = { [K in Stage]?: Runs[K] };
export const endpoints: Record<Stage, string> = {
  transcript: "transcriptions",
  claims: "claim-extractions",
  atoms: "decompositions",
  retrieval: "retrievals",
  mapping: "evidence-mappings",
  ranking: "evidence-rankings",
  verification: "verifications",
  confidence: "confidence-runs",
};
export const stages = Object.keys(endpoints) as Stage[];
export const emptyHistory = (): History => ({
  transcript: [],
  claims: [],
  atoms: [],
  retrieval: [],
  mapping: [],
  ranking: [],
  verification: [],
  confidence: [],
});
